// buildFolderRoots MUST perform the buildFolderRoots operation.
// buildFolderRoots holds the data fields for a buildFolderRoots record.
// [🧰repo⌨️cli💻main🔖engineevents✂️buildfolderroots](repo://p/i/repo/b/b/cli/f/main.go/s/Engine%20Events/d/i/buildFolderRoots)
func buildFolderRoots(folders []Folder) []*TreeNode {
	type folderEntry struct {
		folder *Folder
		node   *TreeNode
	}
	folderMap := make(map[string]*folderEntry)
	for i := range folders {
		f := &folders[i]
		folderMap[f.Path] = &folderEntry{
			folder: f,
			node: &TreeNode{
				Kind:    TreeNodeFolder,
				ID:      f.GetID(),
				Label:   f.Name,
				URI:     f.GetURI(),
				SubKind: string(f.Kind),
				Data:    map[string]interface{}{"path": f.Path, "name": f.Name, "kind": string(f.Kind)},
			},
		}
	}
	var roots []*TreeNode
	for path, fe := range folderMap {
		parentPath := filepath.Dir(path)
		if parent, ok := folderMap[parentPath]; ok {
			parent.node.Children = append(parent.node.Children, fe.node)
			continue
		}
		roots = append(roots, fe.node)
	}
	return roots
}

